import{_ as s,a0 as i,w as c,s as l,ao as o,I as r,x as a,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Linux中安裝Cisco Packet Tracer | LCTT x X-CMD","titleTemplate":false,"description":"Linux中安裝Cisco Packet Tracer | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux中安裝Cisco Packet Tracer | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux中安裝Cisco Packet Tracer | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150126 Installing Cisco Packet tracer in Linux","title":"Linux中安裝Cisco Packet Tracer","tag":"201506","desc":""},"relativePath":"201506/20150126 Installing Cisco Packet tracer in Linux.md","filePath":"[post].md"}'),d={name:"201506/20150126 Installing Cisco Packet tracer in Linux.md"};function u(k,t,g,m,P,T){const e=i("Link");return c(),l("div",null,[t[20]||(t[20]=o(`<h1 id="linux中安裝cisco-packet-tracer" tabindex="-1">Linux中安裝Cisco Packet Tracer <a class="header-anchor" href="#linux中安裝cisco-packet-tracer" aria-label="Permalink to “Linux中安裝Cisco Packet Tracer”">​</a></h1><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/Main_picture.png" alt=""></p><h3 id="cisco-packet-tracer是什麼" tabindex="-1">Cisco Packet tracer是什麼？ <a class="header-anchor" href="#cisco-packet-tracer是什麼" aria-label="Permalink to “Cisco Packet tracer是什麼？”">​</a></h3><p><strong>Cisco Packet Tracer</strong>是一個強大的網絡模擬工具，用於進行Cisco認證時的培訓。它為我們提供了各個路由器和網絡設備的良好的接口視圖，這些模擬設備帶有很多選項，跟使用物理機一樣，我們可以在網絡中使用無限的設備。我們能在單個工程中創建多個網絡，以獲得專業化的訓練。Packet Tracer將提供給我們模擬的應用層協議，如<strong>HTTP</strong>，<strong>DNS</strong>，以及像<strong>RIP</strong>，<strong>OSPF</strong>，<strong>EIGRP</strong>等路由協議。</p><p>現在，它發佈了包含有<strong>ASA 5505防火牆</strong>命令列配置的版本。Packet Tracer通常用於Windows版本，但沒有Linux版本。這裏，我們可以下載並安裝Cisco Packet Tracer。</p><h4 id="新發布的cisco-packet-tracer版本" tabindex="-1">新發布的Cisco Packet Tracer版本： <a class="header-anchor" href="#新發布的cisco-packet-tracer版本" aria-label="Permalink to “新發布的Cisco Packet Tracer版本：”">​</a></h4><p>下一代Cisco Packet Tracer版本將會是Cisco Packet Tracer 6.2，當前還處於開發中。</p><h3 id="我的環境設置" tabindex="-1">我的環境設置： <a class="header-anchor" href="#我的環境設置" aria-label="Permalink to “我的環境設置：”">​</a></h3><p><strong>主機名</strong> : desktop1.unixmen.com</p><p><strong>IP地址</strong> : 192.168.0.167</p><p><strong>操作系統</strong> : Ubuntu 14.04 LTS Desktop</p><pre><code># hostname

# ifconfig | grep inet

# lsb_release -a
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_001.png" alt=""></p><h3 id="步驟-1-首先-我們需要下載cisco-packet-tracer。" tabindex="-1">步驟 1： 首先，我們需要下載Cisco Packet Tracer。 <a class="header-anchor" href="#步驟-1-首先-我們需要下載cisco-packet-tracer。" aria-label="Permalink to “步驟 1： 首先，我們需要下載Cisco Packet Tracer。”">​</a></h3><p>要從官方網站下載Packet Tracer，我們需要持有一個令牌，登入Cisco NetSpace，然後從Offering菜單選擇CCNA &gt; Cisco Packet Tracer來開始下載。如果我們沒有令牌，可以從下面的鏈接中獲得，我已經將它上傳到了Droppox。</p>`,15)),r("p",null,[t[1]||(t[1]=a("官方站點： ",-1)),n(e,{href:"https://www.netacad.com/"},{default:p(()=>[...t[0]||(t[0]=[a("https://www.netacad.com/",-1)])]),_:1})]),t[21]||(t[21]=r("p",null,"大多數人沒有下載Packet Tracer的令牌，出於該原因，我已經將它上傳到了dropbox，你可以從下面的URL獲得Packet Tracer。",-1)),r("p",null,[n(e,{href:"https://www.dropbox.com/s/5evz8gyqqvq3o3v/Cisco%20Packet%20Tracer%206.1.1%20Linux.tar.gz?dl=0"},{default:p(()=>[...t[2]||(t[2]=[a("下載Cisco Packet Tracer 6.1.1",-1)])]),_:1})]),t[22]||(t[22]=r("p",null,[r("img",{src:"http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_002.png",alt:""})],-1)),t[23]||(t[23]=r("h3",{id:"步驟-2-安裝java",tabindex:"-1"},[a("步驟 2： 安裝Java： "),r("a",{class:"header-anchor",href:"#步驟-2-安裝java","aria-label":"Permalink to “步驟 2： 安裝Java：”"},"​")],-1)),t[24]||(t[24]=r("p",null,"要安裝Packet Tracer，我們需要安裝java。我們可以使用默認的倉庫安裝java；或者添加PPA倉庫，然後更新包緩存來安裝java。",-1)),t[25]||(t[25]=r("p",null,"使用以下命令來安裝默認的jre",-1)),t[26]||(t[26]=r("pre",null,[r("code",null,`    # sudo apt-get install default-jre
`)],-1)),t[27]||(t[27]=r("p",null,[r("img",{src:"http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_003.png",alt:""})],-1)),t[28]||(t[28]=r("p",null,"（或者）",-1)),t[29]||(t[29]=r("p",null,"使用下面的步驟來安裝Java Run-time並設置環境。",-1)),r("p",null,[t[4]||(t[4]=a("從官方站點下載Java：",-1)),n(e,{href:"http://www.oracle.com/technetwork/java/javase/downloads/jre8-downloads-2133155.html"},{default:p(()=>[...t[3]||(t[3]=[a("下載Java",-1)])]),_:1})]),t[30]||(t[30]=o(`<pre><code># tar -zxvf jre-8u31-linux-x64.tar.gz
# sudo mkdir -p /usr/lib/jvm
# sudo mv -v jre1.8.0_31 /usr/lib/jvm/
# cd /usr/lib/jvm/
# sudo update-alternatives --install &quot;/usr/bin/java&quot; &quot;java&quot; &quot;/usr/lib/jvm/jre1.8.0_31/bin/java&quot; 1
# sudo update-alternatives --set &quot;java&quot; &quot;/usr/lib/jvm/jre1.8.0_31/bin/java&quot;
</code></pre><p>通過編輯用户參數文件來設置Java環境，並添加路徑相關的參數。當我們添加進用户參數文件後，我們機器上的每個用户都可以用java了。</p><pre><code># sudo vi /etc/profile
</code></pre><p>將以下條目添加到/etc/profile文件中：</p><pre><code>export JAVA_HOME=/usr/lib/jvm/jre1.8.0_31
export PATH=$PATH:/usr/java/jre1.8.0_31/bin
</code></pre><p>運行以下命令來立即激活java路徑。</p><pre><code># . /etc/profile
</code></pre><p>檢查Java版本和環境：</p><pre><code># echo $JAVA_HOME
# java -version
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_004.png" alt=""></p><h3 id="步驟-3-啓用32位架構支持" tabindex="-1">步驟 3： 啓用32位架構支持： <a class="header-anchor" href="#步驟-3-啓用32位架構支持" aria-label="Permalink to “步驟 3： 啓用32位架構支持：”">​</a></h3><p>對於Packet Tracer，我們需要一些32位包。要安裝32位包，我們需要使用以下命令來安裝一些依賴。</p><pre><code># sudo dpkg --add-architecture i386
# sudo apt-get update
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_005.png" alt=""></p><pre><code># sudo apt-get install libc6:i386
# sudo apt-get install lib32z1 lib32ncurses5 lib32bz2-1.0
# sudo apt-get install libnss3-1d:i386 libqt4-qt3support:i386 libssl1.0.0:i386 libqtwebkit4:i386 libqt4-scripttools:i386
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_006.png" alt=""></p><h3 id="步驟-4-解壓並安裝軟件包" tabindex="-1">步驟 4： 解壓並安裝軟件包： <a class="header-anchor" href="#步驟-4-解壓並安裝軟件包" aria-label="Permalink to “步驟 4： 解壓並安裝軟件包：”">​</a></h3><p>使用tar命令來解壓下載的包。</p><pre><code># mv Cisco\\ Packet\\ Tracer\\ 6.1.1\\ Linux.tar.gz\\?dl\\=0 Cisco_Packet_tracer.tar.gz

# tar -zxvf Cisco_Packet_tracer.tar.gz
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_007.png" alt=""></p><p>導航到解壓後的目錄</p><pre><code># cd PacketTracer611Student
</code></pre><p>現在，該開始安裝了。安裝過程很簡單，只需幾秒鐘即可搞定。</p><pre><code># sudo ./install
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_008.png" alt=""></p><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_009.png" alt=""></p><p>要使用Packet Tracer工作，我們需要設置環境，Cisco已經提供了環境腳本，我們需要以root用户來運行該腳本以設置環境變量。</p><pre><code># sudo ./set_ptenv.sh
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_010.png" alt=""></p><p>安裝到此結束。接下來，我們需要為Packet Tracer創建桌面圖標。</p><p>通過創建下面的桌面文件來創建桌面圖標。</p><pre><code># sudo su
# cd /usr/share/applications
# sudo vim packettracer.desktop
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_011.png" alt=""></p><p>使用vim編輯器或你喜愛的那個編輯器來添加以下內容到文件。</p><pre><code>[Desktop Entry]
 Name= Packettracer
 Comment=Networking
 GenericName=Cisco Packettracer
 Exec=/opt/packettracer/packettracer
 Icon=/usr/share/icons/packettracer.jpeg
 StartupNotify=true
 Terminal=false
 Type=Application
</code></pre><p>使用wq!來保存並退出vim。</p><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_012.png" alt=""></p><h3 id="步驟-5-運行packet-tracer" tabindex="-1">步驟 5： 運行Packet Tracer <a class="header-anchor" href="#步驟-5-運行packet-tracer" aria-label="Permalink to “步驟 5： 運行Packet Tracer”">​</a></h3><pre><code># sudo packettracer
</code></pre><p>好了，我們已經成功將Packet Tracer安裝到Linux中。上述安裝步驟適用於所有基於Debian的Linux發行版。</p><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_013.png" alt=""></p><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_014.png" alt=""></p><h3 id="資源" tabindex="-1">資源 <a class="header-anchor" href="#資源" aria-label="Permalink to “資源”">​</a></h3>`,43)),r("p",null,[t[6]||(t[6]=a("主頁：",-1)),n(e,{href:"https://www.netacad.com/"},{default:p(()=>[...t[5]||(t[5]=[a("Netacad",-1)])]),_:1})]),t[31]||(t[31]=r("h3",{id:"尾聲",tabindex:"-1"},[a("尾聲： "),r("a",{class:"header-anchor",href:"#尾聲","aria-label":"Permalink to “尾聲：”"},"​")],-1)),t[32]||(t[32]=r("p",null,"這裏，我們展示瞭如何安裝Packet Tracer到Linux發行版中。希望你們找到了將你們所鍾愛的模擬器安裝到Linux中的方法。",-1)),t[33]||(t[33]=r("hr",null,null,-1)),r("p",null,[t[8]||(t[8]=a("via: ",-1)),n(e,{href:"http://www.unixmen.com/installing-cisco-packet-tracer-linux/"},{default:p(()=>[...t[7]||(t[7]=[a("http://www.unixmen.com/installing-cisco-packet-tracer-linux/",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=a("作者：",-1)),n(e,{href:"http://www.unixmen.com/author/babin/"},{default:p(()=>[...t[9]||(t[9]=[a("babin",-1)])]),_:1}),t[13]||(t[13]=a(" 譯者：",-1)),n(e,{href:"https://github.com/GOLinux"},{default:p(()=>[...t[10]||(t[10]=[a("GOLinux",-1)])]),_:1}),t[14]||(t[14]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[11]||(t[11]=[a("wxy",-1)])]),_:1})]),r("p",null,[t[17]||(t[17]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[15]||(t[15]=[a("LCTT",-1)])]),_:1}),t[18]||(t[18]=a(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:p(()=>[...t[16]||(t[16]=[a("Linux中國",-1)])]),_:1}),t[19]||(t[19]=a(" 榮譽推出",-1))])])}const C=s(d,[["render",u]]);export{f as __pageData,C as default};
